-- Bank soal 50 nomor: 40 LOTS + 10 HOTS; opsi A-D.
-- Jalankan satu kali setelah memastikan tabel public.soal_fikih kosong.
INSERT INTO public.soal_fikih
(pertanyaan, pilihan_a, pilihan_b, pilihan_c, pilihan_d, pilihan_e, kunci_jawaban, pembahasan, kategori, aktif, urutan)
SELECT v.pertanyaan, v.pilihan_a, v.pilihan_b, v.pilihan_c, v.pilihan_d, '', v.kunci, v.pembahasan, v.kategori, true, v.urutan
FROM (VALUES
  ('Apa yang dimaksud dengan taharah?','Bersuci dari hadas dan najis','Membersihkan rumah','Mengganti pakaian','Merapikan tempat tidur','A','Taharah berarti bersuci dari hadas dan najis.','LOTS - Thaharah',1),
  ('Air yang suci dan dapat digunakan untuk bersuci disebut ...','Air mustakmal','Air mutlak','Air najis','Air musyammas','B','Air mutlak adalah air yang suci dan menyucikan.','LOTS - Thaharah',2),
  ('Contoh air mutlak adalah ...','Air teh','Air kopi','Air hujan','Air sirup','C','Air hujan termasuk air mutlak.','LOTS - Thaharah',3),
  ('Hadas kecil dapat dihilangkan dengan ...','Mandi wajib','Wudu','Mencuci pakaian','Istinja saja','B','Wudu digunakan untuk menghilangkan hadas kecil.','LOTS - Thaharah',4),
  ('Hadas besar disucikan dengan ...','Mandi wajib','Wudu saja','Membasuh tangan','Tayamum tanpa sebab','A','Hadas besar disucikan dengan mandi wajib sesuai ketentuan.','LOTS - Thaharah',5),
  ('Salah satu rukun wudu adalah ...','Membaca doa setelah wudu','Membasuh wajah','Menghadap kiblat','Menggunakan air hangat','B','Membasuh wajah termasuk rukun wudu.','LOTS - Thaharah',6),
  ('Batas membasuh kedua tangan dalam wudu adalah sampai ...','Pergelangan tangan','Bahu','Siku','Ujung jari','C','Kedua tangan dibasuh sampai siku.','LOTS - Thaharah',7),
  ('Mengusap sebagian kepala ketika wudu termasuk ...','Rukun wudu','Syarat pakaian','Sunah salat','Pembatal wudu','A','Mengusap kepala merupakan rukun wudu.','LOTS - Thaharah',8),
  ('Tertib dalam wudu berarti ...','Menggunakan air banyak','Melakukan rukun sesuai urutan','Berwudu dengan cepat','Mengulang semua gerakan tiga kali','B','Tertib berarti melaksanakan rukun wudu secara berurutan.','LOTS - Thaharah',9),
  ('Salah satu hal yang membatalkan wudu adalah ...','Membaca Al-Qur''an','Tidur nyenyak','Membasuh wajah','Membaca doa','B','Tidur nyenyak dapat membatalkan wudu.','LOTS - Thaharah',10),
  ('Tayamum dilakukan menggunakan ...','Air laut','Debu atau tanah yang suci','Minyak wangi','Daun kering','B','Tayamum menggunakan debu atau tanah yang suci sesuai ketentuan.','LOTS - Thaharah',11),
  ('Tayamum diperbolehkan ketika ...','Air tersedia dan mudah digunakan','Tidak ada air atau penggunaan air membahayakan','Ingin menghemat waktu saja','Akan bepergian dekat','B','Tayamum merupakan pengganti wudu atau mandi dalam kondisi yang dibenarkan.','LOTS - Thaharah',12),
  ('Najis mukhaffafah berarti najis ...','Berat','Sedang','Ringan','Yang tidak terlihat','C','Mukhaffafah adalah najis ringan.','LOTS - Thaharah',13),
  ('Cara menyucikan najis mughallazah adalah ...','Diusap dengan kain kering','Dibasuh tujuh kali, salah satunya dengan tanah/debu suci','Dijemur sampai kering','Diberi parfum','B','Najis berat disucikan dengan tujuh basuhan, salah satunya menggunakan tanah/debu suci.','LOTS - Thaharah',14),
  ('Istinja adalah kegiatan ...','Membersihkan diri setelah buang hajat','Membasuh kaki sebelum tidur','Mengusap kepala','Mengganti pakaian','A','Istinja dilakukan untuk membersihkan kotoran setelah buang hajat.','LOTS - Thaharah',15),
  ('Benda yang digunakan untuk istinja harus ...','Najis','Suci dan dapat membersihkan','Benda cair berwarna','Makanan','B','Alat istinja harus suci dan mampu membersihkan.','LOTS - Thaharah',16),
  ('Jika pakaian terkena najis, tindakan yang tepat adalah ...','Memakai parfum','Mencuci bagian yang terkena najis hingga suci','Menutupinya dengan kain','Membiarkannya kering','B','Bagian yang terkena najis harus dibersihkan sesuai jenis najisnya.','LOTS - Thaharah',17),
  ('Salah satu hikmah bersuci adalah ...','Menjadi lebih sombong','Menjaga kebersihan dan kesiapan beribadah','Menghindari belajar','Memperlama pekerjaan','B','Bersuci menjaga kebersihan lahir dan mendukung ibadah.','LOTS - Thaharah',18),
  ('Air yang telah digunakan untuk mengangkat hadas dan tidak berubah sifatnya disebut ...','Air mutlak','Air mustakmal','Air najis','Air hujan','B','Air mustakmal adalah air bekas digunakan untuk bersuci menurut pembahasan fikih.','LOTS - Thaharah',19),
  ('Ketika tidak menemukan air untuk berwudu, seorang muslim dapat ...','Meninggalkan salat','Bertayamum sesuai ketentuan','Menggunakan minuman','Menunda salat tanpa alasan','B','Tayamum menjadi pengganti bersuci dengan air ketika syaratnya terpenuhi.','LOTS - Thaharah',20),
  ('Salat menurut istilah adalah ...','Doa tanpa aturan','Ibadah berupa perkataan dan perbuatan tertentu yang diawali takbir dan diakhiri salam','Membaca buku','Kegiatan olahraga','B','Salat memiliki tata cara khusus yang diawali takbiratul ihram dan diakhiri salam.','LOTS - Salat',21),
  ('Salat fardu sehari semalam berjumlah ...','Tiga waktu','Empat waktu','Lima waktu','Enam waktu','C','Salat fardu terdiri atas Subuh, Zuhur, Asar, Magrib, dan Isya.','LOTS - Salat',22),
  ('Jumlah rakaat salat Subuh adalah ...','Dua','Tiga','Empat','Lima','A','Salat Subuh terdiri atas dua rakaat.','LOTS - Salat',23),
  ('Jumlah rakaat salat Magrib adalah ...','Dua','Tiga','Empat','Lima','B','Salat Magrib terdiri atas tiga rakaat.','LOTS - Salat',24),
  ('Salat Zuhur dilaksanakan ketika ...','Matahari terbit','Matahari tergelincir ke barat','Matahari terbenam','Tengah malam','B','Waktu Zuhur dimulai setelah matahari tergelincir ke barat.','LOTS - Salat',25),
  ('Takbiratul ihram dilakukan dengan mengucapkan ...','Subhanallah','Allahu Akbar','Alhamdulillah','Astaghfirullah','B','Takbiratul ihram menggunakan lafaz Allahu Akbar.','LOTS - Salat',26),
  ('Gerakan salat setelah rukuk adalah ...','Sujud','Iktidal','Duduk tahiyat','Salam','B','Setelah rukuk dilakukan iktidal.','LOTS - Salat',27),
  ('Rukun salat yang menandai berakhirnya salat adalah ...','Rukuk','Sujud','Salam','Takbir','C','Salam menjadi penutup rangkaian salat.','LOTS - Salat',28),
  ('Menghadap kiblat ketika salat termasuk ...','Syarat sah salat','Pembatal salat','Sunah wudu','Rukun puasa','A','Menghadap kiblat merupakan syarat sah salat bagi yang mampu.','LOTS - Salat',29),
  ('Menutup aurat ketika salat merupakan ...','Syarat sah salat','Hal yang membatalkan salat','Sunah setelah salat','Syarat zakat','A','Menutup aurat termasuk syarat sah salat.','LOTS - Salat',30),
  ('Makmum ketika salat berjamaah harus ...','Mendahului imam','Mengikuti gerakan imam dan tidak mendahuluinya','Bergerak sendiri','Tidak perlu mengikuti imam','B','Makmum mengikuti imam dengan tertib.','LOTS - Salat',31),
  ('Orang yang memimpin salat berjamaah disebut ...','Muazin','Imam','Makmum','Khatib','B','Imam adalah orang yang memimpin salat berjamaah.','LOTS - Salat',32),
  ('Salat berjamaah paling sedikit dilakukan oleh ...','Satu orang','Dua orang','Tiga orang','Empat orang','B','Salat berjamaah minimal terdiri atas imam dan seorang makmum.','LOTS - Salat',33),
  ('Sujud sahwi dilakukan karena ...','Lupa atau ragu dalam bagian tertentu salat','Sengaja meninggalkan salat','Selesai membaca doa','Akan berangkat sekolah','A','Sujud sahwi disyariatkan untuk menutup kekurangan karena lupa dalam salat.','LOTS - Salat',34),
  ('Salat yang dilakukan untuk memohon petunjuk dalam suatu pilihan disebut ...','Istisqa','Istikharah','Kusuf','Tahajud','B','Salat istikharah dilakukan untuk memohon petunjuk Allah.','LOTS - Salat',35),
  ('Salat sunah rawatib adalah salat sunah yang ...','Mengiringi salat fardu','Dilakukan hanya saat gerhana','Dilakukan saat meminta hujan','Tidak memiliki waktu','A','Rawatib mengiringi salat fardu sebelum atau sesudahnya.','LOTS - Salat',36),
  ('Jika seseorang tidak mampu berdiri ketika salat karena sakit, ia boleh salat dengan ...','Meninggalkan semua gerakan dan bacaan','Duduk sesuai kemampuan','Menunggu sampai sembuh tanpa salat','Meminta orang lain menggantikan','B','Orang sakit melaksanakan salat sesuai kemampuan.','LOTS - Salat',37),
  ('Ketika imam rukuk, makmum yang datang terlambat sebaiknya ...','Berlari dan mendahului imam','Takbiratul ihram lalu mengikuti imam dengan tenang','Langsung sujud','Membatalkan salat berjamaah','B','Makmum masbuk masuk salat dengan tertib dan mengikuti posisi imam.','LOTS - Salat',38),
  ('Seorang siswa selesai berolahraga dan menyadari bajunya terkena najis. Ia akan segera salat. Tindakan paling tepat adalah ...','Langsung salat karena waktunya dekat','Membersihkan bagian yang terkena najis terlebih dahulu','Menyemprotkan parfum pada baju','Menutup bagian itu dengan jaket','B','Pakaian harus suci dari najis untuk memenuhi syarat sah salat.','HOTS - Thaharah',39),
  ('Dalam perjalanan, air yang tersedia sangat terbatas dan diperlukan untuk minum agar tidak kehausan berat. Waktu salat hampir habis. Pilihan yang tepat adalah ...','Menggunakan seluruh air untuk wudu','Bertayamum jika memenuhi ketentuan karena air dibutuhkan untuk keselamatan','Tidak perlu salat','Menunggu sampai tiba di rumah','B','Kebutuhan menjaga keselamatan dapat menjadi alasan tayamum ketika syaratnya terpenuhi.','HOTS - Thaharah',40),
  ('Rina berwudu, tetapi setelah selesai ia melihat ada bagian kecil wajah yang belum terkena air. Apa yang sebaiknya dilakukan?','Mengabaikannya karena wudu sudah selesai','Membasuh bagian yang tertinggal dan menyempurnakan wudu sesuai ketentuan','Mengulang salat tanpa memperbaiki wudu','Mengganti pakaian','B','Bagian wajah termasuk area wajib dibasuh dalam wudu.','HOTS - Thaharah',41),
  ('Ali terkena najis pada lengan baju, sedangkan bagian lain tetap bersih. Cara paling tepat adalah ...','Membuang seluruh pakaian','Mencuci bagian yang terkena najis sampai suci','Membasahi seluruh tubuh','Mengusapnya dengan tangan kering','B','Penyucian dilakukan pada bagian yang terkena najis sesuai jenisnya.','HOTS - Thaharah',42),
  ('Seseorang tidak dapat menggunakan air karena luka akan bertambah parah jika terkena air. Waktu salat telah tiba. Sikap yang tepat adalah ...','Tetap menggunakan air meski membahayakan','Mengambil keringanan bersuci sesuai ketentuan, termasuk tayamum bila memenuhi syarat','Meninggalkan salat','Menunggu luka sembuh','B','Syariat memberi keringanan ketika penggunaan air membahayakan.','HOTS - Thaharah',43),
  ('Dina ragu apakah wudunya batal setelah merasa ada gerakan di perut, tetapi tidak yakin ada sesuatu yang keluar. Prinsip yang tepat adalah ...','Menganggap wudu pasti batal','Mempertahankan keadaan suci sampai ada kepastian batal','Mengulang mandi wajib','Tidak jadi salat','B','Keyakinan tidak hilang karena keraguan semata.','HOTS - Thaharah',44),
  ('Ketika salat berjamaah, seorang makmum bergerak rukuk sebelum imam. Apa perbaikan sikap yang benar?','Tetap mendahului agar cepat','Mengikuti gerakan imam dan tidak mendahuluinya','Keluar dari jamaah','Menghentikan salat','B','Makmum wajib mengikuti imam dan tidak mendahuluinya.','HOTS - Salat',45),
  ('Seorang siswa lupa jumlah rakaat antara tiga atau empat. Sikap yang sesuai tuntunan umum adalah ...','Memilih jumlah yang lebih banyak tanpa dasar','Mengambil jumlah yang diyakini lebih sedikit lalu menyempurnakan dan melakukan sujud sahwi sesuai ketentuan','Langsung salam','Mengulang salat setiap kali ragu','B','Dalam keraguan jumlah rakaat, dibangun di atas yang diyakini dan disempurnakan.','HOTS - Salat',46),
  ('Saat salat, seorang siswa mendengar alarm kebakaran dan melihat guru memberi instruksi evakuasi. Tindakan yang paling tepat adalah ...','Tetap melanjutkan salat tanpa memperhatikan bahaya','Mengutamakan keselamatan dan menghentikan salat bila diperlukan untuk evakuasi','Mematikan alarm lalu kembali','Menyuruh orang lain saja','B','Keselamatan jiwa didahulukan ketika ada keadaan darurat nyata.','HOTS - Salat',47),
  ('Makmum masbuk masuk masjid ketika imam sedang rukuk. Ia ingin memperoleh rakaat bersama imam. Tindakan yang tepat adalah ...','Langsung rukuk tanpa takbiratul ihram','Takbiratul ihram dalam posisi berdiri, lalu mengikuti imam sesuai ketentuan','Menunggu imam salam','Mengikuti dari luar saf','B','Makmum masbuk tetap memulai dengan takbiratul ihram dalam keadaan berdiri jika mampu.','HOTS - Salat',48),
  ('Seorang siswa sering terburu-buru sehingga gerakan rukuk dan sujud tidak tenang. Perbaikan utama yang harus dilakukan adalah ...','Mempercepat bacaan','Melaksanakan tumakninah pada setiap gerakan yang menjadi ketentuannya','Mengurangi rakaat','Mengikuti gerakan teman','B','Tumakninah merupakan unsur penting dalam pelaksanaan salat.','HOTS - Salat',49),
  ('Dalam perjalanan, rombongan siswa tiba di tempat salat dan waktu hampir habis. Sebagian ingin salat sendiri-sendiri agar cepat. Pilihan yang lebih tepat jika kondisi memungkinkan adalah ...','Membentuk salat berjamaah dengan tertib','Menunda sampai waktu habis','Tidak salat karena sedang bepergian','Mengganti salat dengan doa','A','Salat berjamaah dapat dilakukan bila memungkinkan dan membantu menjaga ketertiban ibadah.','HOTS - Salat',50)
) AS v(pertanyaan,pilihan_a,pilihan_b,pilihan_c,pilihan_d,kunci,pembahasan,kategori,urutan)
WHERE NOT EXISTS (
  SELECT 1 FROM public.soal_fikih s WHERE s.pertanyaan = v.pertanyaan
);
